import json
import tomllib
from datetime import date, datetime
from pathlib import Path

config = Path('/config')
out = Path('/out')
out.mkdir(parents=True, exist_ok=True)
with (config / 'base.toml').open('rb') as f:
    base = tomllib.load(f)

def merge(base_value, override_value):
    if isinstance(base_value, dict) and isinstance(override_value, dict):
        result = dict(base_value)
        for key, value in override_value.items():
            if value == '__unset__' and isinstance(value, str):
                result.pop(key, None)
            elif key in result and isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = merge(result[key], value)
            else:
                result[key] = value
        return result
    return override_value

def json_values(value):
    if isinstance(value, dict):
        return {key: json_values(item) for key, item in value.items()}
    if isinstance(value, list):
        return [json_values(item) for item in value]
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    return value

environments = sorted(config.joinpath('env').glob('*.toml'), key=lambda path: path.stem)
for path in environments:
    with path.open('rb') as f:
        override = tomllib.load(f)
    merged = json_values(merge(base, override))
    (out / f'{path.stem}.json').write_text(
        json.dumps(merged, indent=2, sort_keys=True, ensure_ascii=False) + '\n',
        encoding='utf-8',
    )
(out / 'index.txt').write_text(''.join(f'{path.stem}\n' for path in environments), encoding='utf-8')
